///README// 
# Code74k 
 
This util serves Code74k entries through KickLang. 
 
 
 
///Code74k.json// 
[ 
 { 
   "id": "1", 
   "conversations": [ 
     { 
       "from": "human", 
       "value": "What?" 
     }, 
     { 
       "from": "gpt", 
       "value": "Nothing." 
     } 
   ] 
 }, 
 { 
   "id": "2", 
   "conversations": [ 
     { 
       "from": "human", 
       "value": "When?" 
     }, 
     { 
       "from": "gpt", 
       "value": "Now." 
     } 
   ] 
