]

```typescript
import { Util, Node } from "kicklang/lib/core";

export interface Code74kEntry {
  id: string;
  conversations: Code74kConversation[];
}

export interface Code74kConversation {
  from: "human" | "gpt";
  value: string;
}

export class Code74k extends Util {
  entries: Code74kEntry[] = [];

  constructor(ast: Node) {
    super(ast);
    this.init();
  }

  private init() {
    const entries = this.ast.value as Node[];
    entries.forEach((entry) => {
      const id = this.getAttribute(entry, "id");
      const conversations = this.getConversations(entry);
      this.entries.push({ id, conversations });
    });
  }

  private getConversations(entry: Node): Code74kConversation[] {
    const conversations = this.getChild(entry, "conversations").value as Node[];
    return conversations.map((conversation) => {
      const from = this.getAttribute(conversation, "from") as Code74kConversation["from"];
      const value = this.getChildValue(conversation, "value");
      return { from, value };
    });
  }
}
